## 学习目标

通过本教程，你将学会：

- 理解动画的基本概念
- 掌握属性动画的使用
- 学会转场动画的实现
- 掌握手势识别和处理
- 实现自定义动画效果
- 优化动画性能

## 前置知识

- 完成[生命周期管理](/blog/harmony/tutorial/10-lifecycle)
- 了解基本的动画概念（如果有 CSS/Web 动画经验更佳）

## 核心概念

### 动画系统

ArkUI 提供了丰富的动画 API，可以实现流畅的 UI 动画效果。

**对比 Web 开发**：
- CSS `transition` → ArkUI `animateTo`
- CSS `@keyframes` → ArkUI 动画 API
- CSS `transform` → ArkUI 变换属性

## 详细内容

### 1. 属性动画

#### animateTo 基础使用

```typescript
@Entry
@Component
struct AnimationExample {
  @State width: number = 100;
  @State height: number = 100;
  @State opacity: number = 1.0;
  @State angle: number = 0;

  build() {
    Column() {
      // 动画目标元素
      Column() {
        Text('Animated')
      }
      .width(this.width)
      .height(this.height)
      .opacity(this.opacity)
      .rotate({ angle: this.angle })
      .backgroundColor(Color.Blue)
      .margin(20)

      Button('Animate')
        .onClick(() => {
          // 执行动画
          animateTo({
            duration: 1000,        // 动画时长（毫秒）
            curve: Curve.EaseInOut, // 动画曲线
            iterations: 1,        // 重复次数
            playMode: PlayMode.Normal // 播放模式
          }, () => {
            // 修改属性值，自动产生动画
            this.width = 200;
            this.height = 200;
            this.opacity = 0.5;
            this.angle = 180;
          });
        })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}
```

#### 动画曲线

```typescript
// 不同的动画曲线
animateTo({
  duration: 1000,
  curve: Curve.EaseInOut,  // 缓入缓出
  // curve: Curve.EaseIn,   // 缓入
  // curve: Curve.EaseOut,  // 缓出
  // curve: Curve.Linear,   // 线性
  // curve: Curve.Ease,     // 默认缓动
}, () => {
  this.width = 200;
});

// 自定义贝塞尔曲线
animateTo({
  duration: 1000,
  curve: Curve.CubicBezier(0.25, 0.1, 0.25, 1.0)
}, () => {
  this.width = 200;
});
```

**对比 CSS**：类似 `transition: width 1s ease-in-out;`

### 2. 转场动画

#### 页面转场

```typescript
// 页面跳转时使用转场动画
router.pushUrl({
  url: 'pages/Detail',
  params: { id: 123 }
}, router.RouterMode.Standard, (err) => {
  if (err) {
    console.error('Navigation failed');
  }
});
```

#### 组件转场

```typescript
@Entry
@Component
struct TransitionExample {
  @State show: boolean = true;

  build() {
    Column() {
      if (this.show) {
        // 使用 transition 定义转场动画
        Text('Fade In/Out')
          .transition(TransitionEffect.OPACITY.animation({
            duration: 300,
            curve: Curve.EaseInOut
          }))
      }

      Button('Toggle')
        .onClick(() => {
          this.show = !this.show;
        })
    }
  }
}
```

#### 多种转场效果

```typescript
// 淡入淡出
.transition(TransitionEffect.OPACITY)

// 缩放
.transition(TransitionEffect.SCALE)

// 平移
.transition(TransitionEffect.translate({ x: 100, y: 0 }))

// 旋转
.transition(TransitionEffect.ROTATION)

// 组合效果
.transition(
  TransitionEffect.OPACITY
    .combine(TransitionEffect.SCALE)
    .animation({ duration: 300 })
)
```

### 3. 手势识别

#### 点击手势

```typescript
@Entry
@Component
struct GestureExample {
  @State message: string = 'Tap me';

  build() {
    Column() {
      Text(this.message)
        .fontSize(30)
        .gesture(
          TapGesture({ count: 1 })
            .onAction(() => {
              this.message = 'Tapped!';
            })
        )
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}
```

#### 长按手势

```typescript
.gesture(
  LongPressGesture({ duration: 1000 })
    .onAction(() => {
      this.message = 'Long pressed!';
    })
)
```

#### 拖动手势

```typescript
@Entry
@Component
struct DragExample {
  @State offsetX: number = 0;
  @State offsetY: number = 0;

  build() {
    Stack() {
      Column() {
        Text('Drag Me')
      }
      .width(100)
      .height(100)
      .backgroundColor(Color.Blue)
      .translate({ x: this.offsetX, y: this.offsetY })
      .gesture(
        PanGesture({ fingers: 1, direction: PanDirection.All })
          .onActionUpdate((event: GestureEvent) => {
            this.offsetX += event.offsetX;
            this.offsetY += event.offsetY;
          })
      )
    }
    .width('100%')
    .height('100%')
  }
}
```

#### 捏合手势（缩放）

```typescript
@Entry
@Component
struct PinchExample {
  @State scale: number = 1.0;

  build() {
    Column() {
      Image($r('app.media.image'))
        .width(200)
        .height(200)
        .scale({ x: this.scale, y: this.scale })
        .gesture(
          PinchGesture({ fingers: 2 })
            .onActionUpdate((event: GestureEvent) => {
              this.scale = event.scale;
            })
        )
    }
  }
}
```

### 4. 组合手势

#### 手势组合

```typescript
