  Text('Optimized')
}
.willChange(WillChange.Transform)  // 提示浏览器优化
```

#### 避免过度动画

```typescript
// ❌ 不好的做法：同时动画多个属性
animateTo({}, () => {
  this.width = 200;
  this.height = 200;
  this.opacity = 0.5;
  this.angle = 180;
  this.x = 100;
  this.y = 100;
});

// ✅ 好的做法：合并相关属性
animateTo({}, () => {
  this.width = 200;
  this.height = 200;
});
animateTo({}, () => {
  this.opacity = 0.5;
});
```

