## 学习目标

通过本教程，你将学会：

- 理解页面和组件的生命周期
- 掌握页面生命周期回调
- 掌握组件生命周期回调
- 学会资源管理和内存优化
- 理解后台任务处理

## 前置知识

- 完成[数据存储](/blog/harmony/tutorial/09-data-storage)
- 了解基本的应用生命周期概念

## 核心概念

### 生命周期概述

生命周期是组件从创建到销毁的整个过程。理解生命周期有助于：

- 在合适的时机初始化资源
- 及时释放资源，避免内存泄漏
- 处理页面显示/隐藏逻辑

**对比 Web 开发**：

- React `useEffect` → ArkUI 生命周期回调
- Vue `mounted/unmounted` → ArkUI 生命周期回调

## 详细内容

### 1. 页面生命周期

#### 生命周期回调

```typescript
@Entry
@Component
struct LifecyclePage {
  // 页面显示前（仅调用一次）
  aboutToAppear() {
    console.log('Page about to appear');
    // 初始化数据、请求网络等
  }

  // 页面显示时
  onPageShow() {
    console.log('Page shown');
    // 刷新数据、恢复动画等
  }

  // 页面隐藏时
  onPageHide() {
    console.log('Page hidden');
    // 暂停动画、保存状态等
  }

  // 页面销毁前（仅调用一次）
  aboutToDisappear() {
    console.log('Page about to disappear');
    // 清理资源、取消请求等
  }

  build() {
    Column() {
      Text('Lifecycle Demo')
    }
  }
}
```

#### 生命周期流程图

```
页面创建
  ↓
aboutToAppear()  ← 仅调用一次
  ↓
onPageShow()     ← 每次显示时调用
  ↓
[页面可见]
  ↓
onPageHide()     ← 每次隐藏时调用
  ↓
aboutToDisappear() ← 仅调用一次
  ↓
页面销毁
```

### 2. 组件生命周期

#### 组件生命周期回调

```typescript
@Component
struct LifecycleComponent {
  // 组件创建时（仅调用一次）
  aboutToAppear() {
    console.log('Component about to appear');
  }

  // 组件销毁前（仅调用一次）
  aboutToDisappear() {
    console.log('Component about to disappear');
  }

  build() {
    Column() {
      Text('Component')
    }
  }
}
```

**注意**：组件没有 `onPageShow` 和 `onPageHide`，这些是页面级别的回调。

### 3. 资源管理

#### 在生命周期中管理资源

```typescript
@Entry
@Component
struct ResourceManagementPage {
  private timer: number | null = null;
  private httpRequest: http.HttpRequest | null = null;

  aboutToAppear() {
    // 初始化资源
    this.startTimer();
    this.loadData();
  }

  onPageHide() {
    // 页面隐藏时暂停
    this.pauseTimer();
  }

  onPageShow() {
    // 页面显示时恢复
    this.resumeTimer();
  }

  aboutToDisappear() {
    // 清理资源
    this.stopTimer();
    this.cancelRequest();
  }

  startTimer() {
    this.timer = setInterval(() => {
      console.log('Timer tick');
    }, 1000);
  }

  pauseTimer() {
    // 暂停逻辑
  }

  resumeTimer() {
    // 恢复逻辑
  }

  stopTimer() {
    if (this.timer !== null) {
      clearInterval(this.timer);
      this.timer = null;
    }
  }

  async loadData() {
    this.httpRequest = http.createHttp();
    // 请求数据...
  }

  cancelRequest() {
    if (this.httpRequest) {
      this.httpRequest.destroy();
      this.httpRequest = null;
    }
  }

  build() {
    Column() {
      Text('Resource Management')
    }
  }
}
```

### 4. 内存优化

#### 避免内存泄漏

```typescript
@Entry
@Component
struct MemoryOptimizationPage {
  @State data: any[] = [];
  private listeners: (() => void)[] = [];

  aboutToAppear() {
    // 注册事件监听
    this.addListener(() => {
      console.log('Event fired');
    });
  }

  aboutToDisappear() {
    // 移除所有监听器，避免内存泄漏
    this.listeners = [];
  }

  addListener(callback: () => void) {
    this.listeners.push(callback);
  }

  build() {
    Column() {
      // 使用 ForEach 时提供 key，提高性能
      ForEach(this.data, (item: any, index: number) => {
        ListItem() {
          Text(`Item ${index}`)
        }
      }, (item: any, index: number) => `${item.id}-${index}`)
    }
  }
}
```

#### 及时释放大对象

```typescript
@Entry
@Component
struct LargeDataPage {
  @State largeData: number[] = [];

  onPageShow() {
    // 加载大数据
    this.loadLargeData();
  }

  onPageHide() {
    // 页面隐藏时清空大数据，释放内存
    this.largeData = [];
  }

  loadLargeData() {
    // 模拟加载大量数据
    this.largeData = Array.from({ length: 10000 }, (_, i) => i);
  }

  build() {
    Column() {
      Text(`Data count: ${this.largeData.length}`)
    }
  }
}
```

### 5. 后台任务处理

#### 页面进入后台时的处理

```typescript
@Entry
@Component
struct BackgroundTaskPage {
  @State isActive: boolean = true;

  onPageShow() {
    this.isActive = true;
    // 恢复后台任务
