### 6. 数据刷新策略

#### 根据生命周期刷新数据

```typescript
@Entry
@Component
struct DataRefreshPage {
  @State users: User[] = [];
  private lastRefreshTime: number = 0;
  private refreshInterval: number = 5 * 60 * 1000; // 5 分钟

  aboutToAppear() {
    // 首次加载
    this.loadUsers();
  }

  onPageShow() {
    // 检查是否需要刷新
    let now = Date.now();
    if (now - this.lastRefreshTime > this.refreshInterval) {
      this.loadUsers();
    }
  }

  async loadUsers() {
    try {
      this.users = await UserService.getUsers();
      this.lastRefreshTime = Date.now();
    } catch (error) {
      console.error('Failed to load users:', error);
    }
  }

  build() {
    Column() {
      List() {
        ForEach(this.users, (user: User) => {
          ListItem() {
            Text(user.name)
          }
        })
      }
    }
  }
}
```

## 实践练习

### 练习 1：实现页面数据加载

**目标**：在页面显示时加载数据，隐藏时暂停

**要求**：

1. 在 `aboutToAppear` 中初始化
2. 在 `onPageShow` 中刷新数据
3. 在 `onPageHide` 中暂停操作
4. 在 `aboutToDisappear` 中清理资源

**参考代码**：

```typescript
@Entry
@Component
struct DataLoadPage {
  @State data: any[] = [];
  @State loading: boolean = false;
  private refreshTimer: number | null = null;

  aboutToAppear() {
    console.log('Page initializing');
    this.loadData();
  }

  onPageShow() {
    console.log('Page shown, refreshing data');
    this.startAutoRefresh();
  }

  onPageHide() {
    console.log('Page hidden, pausing refresh');
    this.stopAutoRefresh();
  }

  aboutToDisappear() {
    console.log('Page destroying, cleaning up');
    this.stopAutoRefresh();
  }

  async loadData() {
    this.loading = true;
    try {
      // 模拟网络请求
      await new Promise(resolve => setTimeout(resolve, 1000));
      this.data = [1, 2, 3, 4, 5];
    } finally {
      this.loading = false;
    }
  }

  startAutoRefresh() {
    this.refreshTimer = setInterval(() => {
      this.loadData();
    }, 30000); // 每 30 秒刷新
  }

  stopAutoRefresh() {
    if (this.refreshTimer !== null) {
      clearInterval(this.refreshTimer);
      this.refreshTimer = null;
    }
  }

  build() {
    Column() {
      if (this.loading) {
        Text('Loading...')
      } else {
        ForEach(this.data, (item: number) => {
          Text(`Item ${item}`)
        })
      }
    }
  }
}
```

