### 8. 布局性能优化

#### 避免过度嵌套

```typescript
// ❌ 不好的做法：过度嵌套
Column() {
  Column() {
    Column() {
      Column() {
        Text('Content')
      }
    }
  }
}

// ✅ 好的做法：扁平化结构
Column() {
  Text('Content')
    .margin(10)
    .padding(10)
}
```

#### 使用 layoutWeight 替代固定尺寸

```typescript
// ✅ 好的做法：使用 Flex 权重
Row() {
  Text('Left')
    .layoutWeight(1)
  Text('Right')
    .layoutWeight(1)
}

// ❌ 避免：固定尺寸可能导致布局问题
Row() {
  Text('Left')
    .width(200)
  Text('Right')
    .width(200)
}
```

#### 合理使用缓存

```typescript
@Entry
@Component
struct OptimizedLayout {
  @State data: string[] = [];

  build() {
    List() {
      // ForEach 会自动优化渲染
      ForEach(this.data, (item: string, index: number) => {
        ListItem() {
          Text(item)
        }
      }, (item: string) => item)  // 提供 key 生成函数
    }
  }
}
```

