let result = add(5, 3);
let total = sum(1, 2, 3, 4, 5);
```

### 4. 控制流语句

#### if-else 语句

```typescript
let score: number = 85;

if (score >= 90) {
  console.log("优秀");
} else if (score >= 80) {
  console.log("良好");
} else if (score >= 60) {
  console.log("及格");
} else {
  console.log("不及格");
}

// 三元运算符
let grade = score >= 60 ? "及格" : "不及格";
```

#### switch 语句

```typescript
let day: number = 3;
let dayName: string;

switch (day) {
  case 1:
    dayName = "Monday";
    break;
  case 2:
    dayName = "Tuesday";
    break;
  case 3:
    dayName = "Wednesday";
    break;
  default:
    dayName = "Unknown";
}
```

#### for 循环

```typescript
// 传统 for 循环
for (let i = 0; i < 5; i++) {
  console.log(i);
}

// for...of 循环（遍历数组）
let fruits = ["apple", "banana", "orange"];
for (let fruit of fruits) {
  console.log(fruit);
}

// for...in 循环（遍历对象属性）
