        }
        .layoutWeight(1)
      }
      .width('100%')

      Row() {
        Column() {
          Text('1/3')
        }
        .width('33.33%')

        Column() {
          Text('1/3')
        }
        .width('33.33%')

        Column() {
          Text('1/3')
        }
        .width('33.33%')
      }
      .width('100%')
