## 项目需求

### 项目名称：个人记账应用

创建一个简单的个人记账应用，帮助用户记录日常收支。

### 功能需求

1. **记账功能**：

   - 添加收入记录
   - 添加支出记录
   - 记录金额、类别、备注、时间

2. **统计功能**：

   - 显示总收入和总支出
   - 显示余额
   - 按类别统计

3. **列表功能**：

   - 显示所有记账记录
   - 支持删除记录
   - 按时间排序

4. **数据持久化**：
   - 使用 Preferences 保存数据
   - 应用重启后数据不丢失

## 项目实现

### 步骤 1：项目结构设计

```
AccountApp/
├── entry/
│   └── src/
│       └── main/
│           ├── ets/
│           │   ├── pages/
│           │   │   ├── Index.ets          # 主页面
│           │   │   └── AddRecord.ets      # 添加记录页面
│           │   ├── models/
│           │   │   └── Record.ets          # 数据模型
│           │   ├── utils/
│           │   │   └── Storage.ets        # 数据存储工具
│           │   └── components/
│           │       └── RecordItem.ets     # 记录项组件
│           └── resources/
```

### 步骤 2：数据模型定义

```typescript
// models/Record.ets
export enum RecordType {
  INCOME = "income", // 收入
  EXPENSE = "expense", // 支出
}

export enum Category {
  FOOD = "food", // 餐饮
  TRANSPORT = "transport", // 交通
  SHOPPING = "shopping", // 购物
  ENTERTAINMENT = "entertainment", // 娱乐
  SALARY = "salary", // 工资
  BONUS = "bonus", // 奖金
  OTHER = "other", // 其他
}

export interface Record {
  id: string;
  type: RecordType;
  amount: number;
  category: Category;
  note: string;
  date: number; // 时间戳
}
```

### 步骤 3：数据存储工具

```typescript
// utils/Storage.ets
import preferences from "@ohos.data.preferences";
import { Record } from "../models/Record";

export class Storage {
  private static context = getContext(this);
  private static store: preferences.Preferences | null = null;

  // 初始化存储
  static async init() {
    if (!this.store) {
      this.store = await preferences.getPreferences(
        this.context,
        "account_data"
      );
    }
  }

  // 保存记录列表
  static async saveRecords(records: Record[]) {
    await this.init();
    const recordsJson = JSON.stringify(records);
    await this.store.put("records", recordsJson);
    await this.store.flush();
  }

  // 获取记录列表
  static async getRecords(): Promise<Record[]> {
    await this.init();
    const recordsJson = await this.store.get("records", "[]");
    return JSON.parse(recordsJson as string);
  }
}
```

### 步骤 4：主页面实现

```typescript
// pages/Index.ets
import { Record, RecordType, Category } from '../models/Record';
import { Storage } from '../utils/Storage';
import router from '@ohos.router';

@Entry
@Component
struct Index {
  @State records: Record[] = [];
  @State totalIncome: number = 0;
  @State totalExpense: number = 0;

  async aboutToAppear() {
    await this.loadRecords();
    this.calculateTotal();
  }

  // 加载记录
  async loadRecords() {
    this.records = await Storage.getRecords();
  }

  // 计算总额
  calculateTotal() {
    this.totalIncome = this.records
      .filter(r => r.type === RecordType.INCOME)
      .reduce((sum, r) => sum + r.amount, 0);

    this.totalExpense = this.records
      .filter(r => r.type === RecordType.EXPENSE)
      .reduce((sum, r) => sum + r.amount, 0);
  }

  // 删除记录
  async deleteRecord(id: string) {
    this.records = this.records.filter(r => r.id !== id);
    await Storage.saveRecords(this.records);
    this.calculateTotal();
  }

  // 跳转到添加页面
  navigateToAdd() {
    router.pushUrl({
      url: 'pages/AddRecord',
      params: {
        onAdd: async () => {
          await this.loadRecords();
          this.calculateTotal();
