      Text('类别: ' + this.category)
        .fontSize(16)
        .margin({ bottom: 20 })

      // 备注输入
      TextArea({ placeholder: '备注（可选）' })
        .width('100%')
        .height(100)
        .onChange((value: string) => {
          this.note = value;
        })
        .margin({ bottom: 20 })

      // 保存按钮
      Button('保存')
        .width('100%')
