## 项目实战

### 项目：待办事项应用（简化版）

**目标**：创建一个简单的待办事项应用

**功能要求**：

1. 显示待办事项列表
2. 添加新待办事项
3. 标记完成/未完成
4. 删除待办事项

**实现步骤**：

1. 定义待办事项数据模型
2. 使用 @State 管理待办事项列表
3. 实现添加、删除、标记功能
4. 使用 List 组件显示列表

**参考代码结构**：

```typescript
// 数据模型
interface TodoItem {
  id: number;
  title: string;
  completed: boolean;
}

@Entry
@Component
struct TodoApp {
  @State todos: TodoItem[] = [];
  @State newTodo: string = '';
  private nextId: number = 1;

  // 添加待办事项
  addTodo() {
    if (this.newTodo.trim()) {
      this.todos.push({
        id: this.nextId++,
        title: this.newTodo,
        completed: false
      });
      this.newTodo = '';
    }
  }

  // 切换完成状态
  toggleTodo(id: number) {
    const todo = this.todos.find(item => item.id === id);
    if (todo) {
      todo.completed = !todo.completed;
    }
  }

  // 删除待办事项
  deleteTodo(id: number) {
    this.todos = this.todos.filter(item => item.id !== id);
  }

  build() {
    Column() {
      // 输入框和添加按钮
      Row() {
        TextInput({ placeholder: '输入待办事项' })
          .layoutWeight(1)
          .onChange((value: string) => {
            this.newTodo = value;
          })

        Button('添加')
          .margin({ left: 10 })
          .onClick(() => {
            this.addTodo();
          })
      }
      .width('100%')
      .padding(10)

      // 待办事项列表
      List() {
        ForEach(this.todos, (todo: TodoItem) => {
          ListItem() {
            Row() {
              Text(todo.title)
                .fontSize(18)
                .decoration({ type: todo.completed ? TextDecorationType.LineThrough : TextDecorationType.None })
                .layoutWeight(1)

              Button(todo.completed ? '未完成' : '完成')
                .margin({ right: 10 })
                .onClick(() => {
                  this.toggleTodo(todo.id);
                })

              Button('删除')
                .onClick(() => {
                  this.deleteTodo(todo.id);
                })
            }
            .width('100%')
            .padding(10)
          }
        })
      }
      .layoutWeight(1)
      .width('100%')
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
}
```

